    (r'new\s+SupabaseClient\s*\(', 'new SupabaseClient()'),
    (r'createSupabaseClient\s*\(', 'createSupabaseClient()'),
    (r'initSupabase\s*\(', 'initSupabase()'),
]

files_scanned = 0
client_creations = []
for root, dirs, files in os.walk('expo'):
    if 'node_modules' in root or '.git' in root:
        continue
    for f in files:
        if f.endswith(('.ts', '.tsx', '.js')):
            path = os.path.join(root, f)
            try:
                with open(path, 'r') as fh:
                    content = fh.read()
                files_scanned += 1
                for pattern, label in client_patterns:
                    matches = re.findall(pattern, content)
                    if matches:
                        client_creations.append((path, label, len(matches)))
            except: pass

for root, dirs, files in os.walk('backend'):
    if 'node_modules' in root or '.git' in root:
        continue
    for f in files:
        if f.endswith(('.ts', '.js')):
            path = os.path.join(root, f)
            try:
                with open(path, 'r') as fh:
                    content = fh.read()
                files_scanned += 1
                for pattern, label in client_patterns:
                    matches = re.findall(pattern, content)
                    if matches:
                        client_creations.append((path, label, len(matches)))
            except: pass

print(f"Files scanned: {files_scanned}")
print(f"Supabase client creation points: {len(client_creations)}")
for path, label, count in client_creations[:20]:
    print(f"  {path}: {label} x{count}")

# 2. Check for service-role key in client bundle
print("\n--- Service-role key in client bundle check ---")
sr_patterns = [
    r'SERVICE_ROLE_KEY',
    r'service_role',
    r'serviceRoleKey',
    r'service-role',
]
sr_findings = []
for root, dirs, files in os.walk('expo'):
    if 'node_modules' in root or '.git' in root:
        continue
    for f in files:
        if f.endswith(('.ts', '.tsx', '.js')):
            path = os.path.join(root, f)
            try:
                with open(path, 'r') as fh:
                    content = fh.read()
                for pattern in sr_patterns:
                    if re.search(pattern, content, re.IGNORECASE):
                        sr_findings.append((path, pattern))
            except: pass

print(f"Service-role references in expo/: {len(sr_findings)}")
for path, pattern in sr_findings[:10]:
    print(f"  {path}: matches '{pattern}'")

# 3. Check for hardcoded passwords, local comparisons, fake sessions
print("\n--- Security anti-patterns check ---")
anti_patterns = [
    (r'password\s*===\s*["\']', 'hardcoded password comparison'),
    (r'isAdmin\s*=\s*true', 'client-side admin override'),
    (r'role\s*=\s*["\']owner["\']', 'client-side role assignment'),
    (r'fakeSession|mockSession', 'fake session'),
    (r'createMockJwt|fakeJwt', 'fake JWT'),
]
anti_findings = []
for root, dirs, files in os.walk('expo'):
    if 'node_modules' in root or '.git' in root:
        continue
    for f in files:
        if f.endswith(('.ts', '.tsx', '.js')):
            path = os.path.join(root, f)
            try:
                with open(path, 'r') as fh:
                    content = fh.read()
                for pattern, label in anti_patterns:
                    if re.search(pattern, content, re.IGNORECASE):
                        anti_findings.append((path, label))
            except: pass

print(f"Security anti-patterns found: {len(anti_findings)}")
for path, label in anti_findings[:10]:
    print(f"  {path}: {label}")

# 4. Check canonical config source
print("\n--- Canonical config source ---")
config_files = [
    'expo/lib/supabase.ts',
    'expo/lib/supabase-client.ts',
    'expo/lib/auth.ts',
    'expo/lib/ivx-config.ts',
    'expo/ivxholding-landing/ivx-config.json',
    'expo/ivxholding-landing/ivx-invest.js',
    'expo/ivxholding-landing/ivx-portal.js',
]
for f in config_files:
    if os.path.exists(f):
        with open(f, 'r') as fh:
            content = fh.read()
        has_url = 'SUPABASE_URL' in content or 'supabase.co' in content
        has_key = 'ANON_KEY' in content or 'anon_key' in content or 'publishableKey' in content
        has_sr = 'SERVICE_ROLE' in content
        print(f"  [{'EXISTS' if True else 'MISSING'}] {f}: url={has_url}, anon_key={has_key}, service_role={has_sr}")

# 5. Check all use the same Supabase project
print("\n--- Supabase project reference consistency ---")
project_refs = set()
for root, dirs, files in os.walk('expo'):
    if 'node_modules' in root or '.git' in root:
        continue
    for f in files:
        if f.endswith(('.ts', '.tsx', '.js', '.json')):
            path = os.path.join(root, f)
            try:
                with open(path, 'r') as fh:
                    content = fh.read()
                refs = re.findall(r'([a-z0-9]{20})\.supabase\.co', content)
                for ref in refs:
                    project_refs.add(ref)
            except: pass
print(f"Unique Supabase project refs in expo/: {project_refs}")
