import os, re

print("=" * 70)
print("PHASE 2 — SERVICE-ROLE KEY IN CLIENT BUNDLE (deep audit)")
print("=" * 70)

# The 44 service-role references in expo/ need verification.
# Key question: are any of them in the CLIENT BUNDLE (app/ screens, lib/), 
# or only in API routes (app/api/*) and admin debug tools?

categories = {
    'api_routes (server-side, OK)': [],
    'admin_debug (admin-only, OK if gated)': [],
    'client_screens (POTENTIAL ISSUE)': [],
    'lib (POTENTIAL ISSUE)': [],
    'tests (OK)': [],
    'other': [],
}

sr_files = []
for root, dirs, files in os.walk('expo'):
    if 'node_modules' in root or '.git' in root:
        continue
    for f in files:
        if f.endswith(('.ts', '.tsx', '.js')):
            path = os.path.join(root, f)
            try:
                with open(path, 'r') as fh:
                    content = fh.read()
                if re.search(r'SERVICE_ROLE_KEY|service_role|serviceRoleKey|service-role', content, re.IGNORECASE):
                    sr_files.append((path, content))
            except: pass

for path, content in sr_files:
    if '/api/' in path or '+api' in path:
        categories['api_routes (server-side, OK)'].append(path)
    elif '__tests__' in path or '.test.' in path:
        categories['tests (OK)'].append(path)
    elif 'backend-audit' in path or 'security-settings' in path or 'owner-access' in path:
        categories['admin_debug (admin-only, OK if gated)'].append(path)
    elif '/lib/' in path:
        categories['lib (POTENTIAL ISSUE)'].append(path)
    elif '/app/' in path and '/api/' not in path:
        categories['client_screens (POTENTIAL ISSUE)'].append(path)
    else:
        categories['other'].append(path)

for cat, files in categories.items():
    print(f"\n{cat}: {len(files)} files")
    for f in files[:8]:
        print(f"  {f}")
        # Check if it actually USES the service-role key (not just mentions it in a comment/error message)
        with open(f, 'r') as fh:
            content = fh.read()
        # Look for actual usage (not just error messages)
        uses = re.findall(r'createClient\s*\([^)]*service[Rr]ole[Kk]ey|process\.env\.SUPABASE_SERVICE_ROLE_KEY', content)
        if uses:
            print(f"    ⚠ ACTUAL USAGE: {uses[0][:60]}")
        else:
            # Check if it's just in a string/message
            msgs = re.findall(r'["\'][^"\']*SERVICE_ROLE[^"\']*["\']', content)
            if msgs:
                print(f"    (string/message only: {msgs[0][:60]}...)")

# Check the main client entry points
print("\n--- Main client entry point check ---")
entry_points = [
    'expo/lib/supabase.ts',
    'expo/lib/ivx-supabase-client.ts',
    'expo/lib/auth-context.tsx',
    'expo/app/_layout.tsx',
]
for f in entry_points:
    if os.path.exists(f):
        with open(f, 'r') as fh:
            content = fh.read()
        has_sr = bool(re.search(r'SERVICE_ROLE_KEY|service_role', content, re.IGNORECASE))
        has_create = 'createClient' in content
        print(f"  {f}: service_role_ref={has_sr}, createClient={has_create}")
        if has_sr:
            # Show the context
            for m in re.finditer(r'.{0,80}(SERVICE_ROLE_KEY|service_role|serviceRoleKey).{0,80}', content, re.IGNORECASE):
                print(f"    context: ...{m.group(0)}...")
PYEOF

